"use client";

import { useState, useEffect } from "react";
import { usePathname } from "next/navigation";
import Link from "next/link";
import { Rocket, X } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

export default function FloatingAgentButton() {
    const pathname = usePathname();
    const [isVisible, setIsVisible] = useState(false);
    const [isDismissed, setIsDismissed] = useState(false);

    // Hide on admin, dashboard, and registration pages
    if (
        pathname.startsWith("/admin") ||
        pathname.startsWith("/agent-dashboard") ||
        pathname === "/agent-register" ||
        pathname === "/agent-login"
    ) {
        return null;
    }

    useEffect(() => {
        const handleScroll = () => {
            // Show button after scrolling 300px
            if (window.scrollY > 300) {
                setIsVisible(true);
            } else {
                setIsVisible(false);
            }
        };

        window.addEventListener("scroll", handleScroll);
        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    if (isDismissed) {
        return null;
    }

    return (
        <AnimatePresence>
            {isVisible && (
                <motion.div
                    initial={{ scale: 0, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    exit={{ scale: 0, opacity: 0 }}
                    transition={{ type: "spring", stiffness: 260, damping: 20 }}
                    className="fixed bottom-6 right-6 z-50 lg:hidden"
                >
                    {/* Dismiss button */}
                    <button
                        onClick={() => setIsDismissed(true)}
                        className="absolute -top-2 -left-2 w-6 h-6 bg-gray-800 text-white rounded-full flex items-center justify-center hover:bg-gray-700 transition-colors shadow-lg z-10"
                        aria-label="إخفاء الزر"
                    >
                        <X className="h-3 w-3" />
                    </button>

                    {/* Main button */}
                    <Link
                        href="/agent-register"
                        className="flex items-center gap-3 bg-secondary text-white px-6 py-4 rounded-full shadow-2xl shadow-secondary/40 hover:shadow-secondary/60 hover:bg-secondary-dark transition-all transform hover:scale-105 active:scale-95"
                    >
                        <Rocket className="h-5 w-5" />
                        <span className="font-bold text-sm">سجّل كوكيل</span>
                    </Link>

                    {/* Pulsing ring effect */}
                    <div className="absolute inset-0 rounded-full bg-secondary/30 animate-ping -z-10" />
                </motion.div>
            )}
        </AnimatePresence>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { usePathname } from "next/navigation";
import { motion, AnimatePresence } from 'framer-motion';

const messages = [
    "🎓 خصم خاص للتسجيل المبكر - سارع بحجز مقعدك الآن!",
    "✈️ خدمات استقبال من المطار وسكن مؤمن لجميع طلابنا الجدد",
    "🌟 استشارات مجانية طوال الأسبوع - تواصل معنا الآن",
];

export default function MarketingBanner() {
    const pathname = usePathname();
    const [index, setIndex] = useState(0);

    if (pathname.startsWith("/admin") || pathname.startsWith("/agent-dashboard")) {
        return null;
    }

    useEffect(() => {
        const timer = setInterval(() => {
            setIndex((prev) => (prev + 1) % messages.length);
        }, 5000);
        return () => clearInterval(timer);
    }, []);

    return (
        <div className="bg-secondary text-primary-dark font-bold text-sm py-2 overflow-hidden relative z-50">
            <div className="container mx-auto px-4 text-center">
                <AnimatePresence mode="wait">
                    <motion.div
                        key={index}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -20 }}
                        transition={{ duration: 0.5 }}
                    >
                        {messages[index]}
                    </motion.div>
                </AnimatePresence>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Building2, GraduationCap, MapPin, Search } from "lucide-react";
import { cn } from "@/lib/utils";
import FadeIn from "./FadeIn";

type University = {
    id: number;
    name: string;
    city: string;
    type: "Government" | "Private";
    description: string;
};

export default function Universities() {
    const [activeTab, setActiveTab] = useState<"Government" | "Private">("Government");
    const [searchTerm, setSearchTerm] = useState("");
    const [universities, setUniversities] = useState<University[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const DUMMY_DATA: University[] = [
        {
            id: 1,
            name: "جامعة توكات (Tokat)",
            city: "توكات",
            type: "Government",
            description: "جامعة حكومية تقع في مدينة توكات التاريخية، تتميز ببيئة تعليمية غنية تجمع بين التراث والحداثة، وتوفر مجموعة واسعة من التخصصات الأكاديمية."
        },
        {
            id: 2,
            name: "جامعة كارابوك (Karabük)",
            city: "كارابوك",
            type: "Government",
            description: "تقع في منطقة البحر الأسود الغربية، وتشتهر بحرمها الجامعي الأخضر وقربها من مدينة سفرانبولو التاريخية، وتتميز بتنوع طلابي دولي كبير."
        },
        {
            id: 3,
            name: "جامعة بولو ابانت عزت بايسال (Bolu Abant İzzet Baysal)",
            city: "بولو",
            type: "Government",
            description: "تتميز بموقع استراتيجي بين إسطنبول وأنقرة، وتُعرف بجمال طبيعتها الخلابة وجودة التعليم، مما يوفر بيئة دراسية هادئة ومثالية."
        },
        {
            id: 4,
            name: "جامعة باتمان (Batman)",
            city: "باتمان",
            type: "Government",
            description: "جامعة حديثة تركز على مجالات الطاقة والتنمية الإقليمية، وتعمل تحت شعار 'تحويل المعرفة إلى طاقة' في مدينة باتمان الغنية بالموارد."
        },
        {
            id: 5,
            name: "جامعة بيلجيك (Bilecik Şeyh Edebali)",
            city: "بيلجيك",
            type: "Government",
            description: "تأسست عام 2007 وتتميز بحرم جامعي حيوي ومرافق حديثة، وتقع في نقطة تقاطع مهمة وقريبة من المدن الكبرى مثل إسطنبول وبورصة."
        },
        {
            id: 6,
            name: "جامعة سيفاس (Sivas Cumhuriyet)",
            city: "سيفاس",
            type: "Government",
            description: "تمتلك خامس أكبر حرم جامعي في تركيا، وتقدم تعليماً عريقاً في بيئة طبيعية واسعة، وتعتبر مركزاً مهماً للبحث العلمي في المنطقة."
        },
        {
            id: 7,
            name: "جامعة غوموشهانه (Gümüşhane)",
            city: "غوموشهانه",
            type: "Government",
            description: "جامعة فتية نامية تقع في شمال شرق تركيا، تتميز بحرم جامعي عصري ومرافق رياضية واجتماعية متكاملة وسط الطبيعة الجبلية."
        },
        {
            id: 8,
            name: "جامعة ساكاريا (Sakarya)",
            city: "ساكاريا",
            type: "Government",
            description: "واحدة من الجامعات البحثية الرائدة، تقع بالقرب من بحيرة صبنجة الخلابة، وتتميز بقربها الكبير من إسطنبول وجودة برامجها الهندسية والإدارية."
        },
        {
            id: 9,
            name: "جامعة كوجالي (Kocaeli)",
            city: "كوجالي",
            type: "Government",
            description: "تقع في القلب الصناعي لتركيا، وتتميز بحرم 'أوموت تيبي' الجامعي الحديث الذي يوفر بيئة تعليمية متكاملة بعيداً عن ضجيج المدينة."
        },
        {
            id: 10,
            name: "جامعة دوزجه (Düzce)",
            city: "دوزجه",
            type: "Government",
            description: "جامعة تتميز بمشاريعها التنموية وتسميتها كجامعة منتجة للقيمة، تقع في موقع متوسط بين أنقرة وإسطنبول وتتمتع ببيئة خضراء."
        }
    ];

    useEffect(() => {
        // Simulate API fetch delay
        const timer = setTimeout(() => {
            setUniversities(DUMMY_DATA);
            setIsLoading(false);
        }, 800);
        return () => clearTimeout(timer);
    }, []);

    const filteredUniversities = universities.filter(u =>
        u.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        u.city.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div id="universities" className="bg-gray-50 py-24 sm:py-32 relative overflow-hidden">
            {/* Background decoration */}
            <div className="absolute top-0 right-0 -mr-24 -mt-24 w-96 h-96 rounded-full bg-secondary/5 blur-3xl z-0" />
            <div className="absolute bottom-0 left-0 -ml-24 -mb-24 w-96 h-96 rounded-full bg-primary/5 blur-3xl z-0" />

            <div className="mx-auto max-w-7xl px-6 lg:px-8 relative z-10">
                <div className="mx-auto max-w-2xl text-center">
                    <h2 className="text-base font-semibold leading-7 text-secondary">الجامعات التركية</h2>
                    <p className="mt-2 text-3xl font-bold tracking-tight text-primary sm:text-4xl">
                        اختر وجهتك الأكاديمية
                    </p>
                    <p className="mt-6 text-lg leading-8 text-gray-600">
                        قائمة مختارة من أفضل الجامعات التركية، تعرف على نبذة مختصرة عن كل جامعة وموقعها.
                    </p>
                </div>

                <div className="mt-12 flex flex-col items-center gap-6">
                    {/* Search */}
                    <div className="relative w-full max-w-lg">
                        <div className="absolute inset-y-0 right-0 flex items-center pr-4 pointer-events-none">
                            <Search className="h-5 w-5 text-gray-400" />
                        </div>
                        <input
                            type="text"
                            className="block w-full rounded-2xl border-0 py-4 pr-12 pl-4 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-200 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-secondary/50 sm:text-sm sm:leading-6 transition-all focus:scale-[1.01]"
                            placeholder="ابحث باسم الـجــامــعــة أو المدينة..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                </div>

                <div className="mt-16 grid grid-cols-1 gap-8 sm:grid-cols-2 lg:grid-cols-3">
                    {isLoading ? (
                        Array.from({ length: 3 }).map((_, i) => (
                            <div key={i} className="bg-white rounded-3xl p-6 shadow-sm border border-gray-100 h-64 animate-pulse flex flex-col gap-4">
                                <div className="h-16 w-16 bg-gray-200 rounded-full" />
                                <div className="h-6 w-3/4 bg-gray-200 rounded" />
                                <div className="h-4 w-full bg-gray-200 rounded" />
                                <div className="mt-auto h-4 w-1/2 bg-gray-200 rounded" />
                            </div>
                        ))
                    ) : filteredUniversities.length > 0 ? (
                        filteredUniversities.map((uni, index) => (
                            <FadeIn key={uni.id} delay={index * 0.05} className="group relative flex flex-col bg-white rounded-3xl shadow-sm hover:shadow-xl transition-all duration-300 border border-gray-100 hover:border-secondary/30 overflow-hidden hover:-translate-y-1">
                                <div className="absolute inset-0 bg-gradient-to-b from-transparent to-gray-50/50 opacity-0 group-hover:opacity-100 transition-opacity" />

                                <div className="p-8 flex flex-col h-full relative z-10">
                                    <div className="flex items-start justify-between mb-6">
                                        <div className={cn("p-3 rounded-2xl", uni.type === "Government" ? "bg-primary/10 text-primary" : "bg-secondary/10 text-secondary")}>
                                            {uni.type === "Government" ? <Building2 className="h-8 w-8" /> : <GraduationCap className="h-8 w-8" />}
                                        </div>
                                        <div className="flex items-center gap-1.5 text-xs font-medium text-gray-500 bg-gray-100 px-3 py-1 rounded-full">
                                            <MapPin className="h-3 w-3" />
                                            {uni.city}
                                        </div>
                                    </div>

                                    <h3 className="text-2xl font-bold text-gray-900 mb-4 group-hover:text-primary transition-colors">{uni.name}</h3>
                                    <p className="text-sm text-gray-600 mb-6 leading-relaxed">{uni.description}</p>
                                </div>
                            </FadeIn>
                        ))
                    ) : (
                        <div className="col-span-full py-20 text-center">
                            <div className="bg-gray-50 rounded-full w-20 h-20 flex items-center justify-center mx-auto mb-4">
                                <Search className="h-8 w-8 text-gray-400" />
                            </div>
                            <h3 className="text-lg font-bold text-gray-900">لا توجد نتائج</h3>
                            <p className="text-gray-500 mt-2">جرب البحث عن جامعة أخرى أو مدينة مختلفة.</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}
